solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <optional>
#include <vector>

struct SectionHeader { std::uint32_t virtualAddress, virtualSize, rawSize, pointerToRawData; };

std::optional<std::uint32_t> rvaToOffset(const std::vector<SectionHeader>& sections, std::uint32_t rva)
{
    for (const SectionHeader& s : sections)
    {
        const std::uint64_t start{ s.virtualAddress };
        const std::uint64_t end{ start + std::max(s.virtualSize, s.rawSize) };
        if (rva < start || rva >= end) continue;
        const std::uint32_t into{ rva - s.virtualAddress };
        if (into >= s.rawSize) return std::nullopt;            // zero-filled: nothing in the file
        return s.pointerToRawData + into;
    }
    return std::nullopt;
}

unitTests:
const std::vector<SectionHeader> table{ { 0x5000, 0x2000, 0x200, 0x4000 }, { 0x1000, 0x3A10, 0x3C00, 0x400 } };
TEST("inside .text") { CHECK_EQ(*rvaToOffset(table, 0x1234), 0x634u); }
TEST("the first byte of a section") { CHECK_EQ(*rvaToOffset(table, 0x1000), 0x400u); }
TEST("inside .data's file data") { CHECK_EQ(*rvaToOffset(table, 0x5100), 0x4100u); }
TEST("zero-filled part of .data") { CHECK(!rvaToOffset(table, 0x5300).has_value()); }
TEST("raw data longer than the virtual size") { CHECK_EQ(*rvaToOffset(table, 0x4B00), 0x3F00u); }
TEST("between sections") { CHECK(!rvaToOffset(table, 0x4C00).has_value()); }
TEST("before the first section and past the last") { CHECK(!rvaToOffset(table, 0x10).has_value()); CHECK(!rvaToOffset(table, 0x9000).has_value()); }

